import path from 'node:path';
import fs from 'node:fs';
import { config } from '../config';

/**
 * Thrown whenever a requested path would escape a session's simulation
 * directory, or is otherwise unsafe. Routes map this to HTTP 400.
 */
export class PathSecurityError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'PathSecurityError';
  }
}

/**
 * Session ids are generated by us as `session_<6 hex>` (see sessionManager).
 * Validating the id here closes a second traversal vector: a caller could
 * otherwise pass `../../other` as the sessionId itself.
 */
const SESSION_ID_RE = /^session_[a-f0-9]{6}$/;

export function assertValidSessionId(sessionId: string): void {
  if (typeof sessionId !== 'string' || !SESSION_ID_RE.test(sessionId)) {
    throw new PathSecurityError(`Invalid session id: ${JSON.stringify(sessionId)}`);
  }
}

/** Absolute path to a session's simulation root: sessions/<id>/simulation */
export function simulationRoot(sessionId: string): string {
  assertValidSessionId(sessionId);
  return path.join(config.sessionsDir, sessionId, 'simulation');
}

/**
 * Walk from `target` up toward `root`, returning the deepest ancestor that
 * actually exists on disk. Used to detect symlink escapes for paths that are
 * about to be created (the file itself may not exist yet, but its parent does).
 */
function deepestExistingAncestor(target: string, root: string): string {
  let current = target;
  // Never climb above the root.
  while (current !== root && current.startsWith(root + path.sep)) {
    if (fs.existsSync(current)) return current;
    const parent = path.dirname(current);
    if (parent === current) break;
    current = parent;
  }
  return root;
}

/** True when `child` is `parent` itself or lives inside it. */
function isInside(parent: string, child: string): boolean {
  if (child === parent) return true;
  return child.startsWith(parent + path.sep);
}

/**
 * Resolve a caller-supplied relative path against a session's simulation root
 * and return the absolute, verified path.
 *
 * Rejects (spec §18):
 *   - absolute paths and Windows drive paths
 *   - `..` traversal that escapes the simulation root
 *   - null bytes
 *   - symbolic-link escapes
 *
 * The returned path is guaranteed to live inside sessions/<id>/simulation/.
 */
export function resolveSafePath(sessionId: string, relPath: string): string {
  const root = simulationRoot(sessionId);

  if (typeof relPath !== 'string' || relPath.length === 0) {
    throw new PathSecurityError('Path must be a non-empty string');
  }
  if (relPath.includes('\0')) {
    throw new PathSecurityError('Path contains a null byte');
  }
  // Normalise separators so Windows-style `..\..\x` is caught too.
  const normalizedInput = relPath.replace(/\\/g, '/');
  if (path.isAbsolute(relPath) || path.isAbsolute(normalizedInput) || /^[a-zA-Z]:/.test(relPath)) {
    throw new PathSecurityError(`Absolute paths are not allowed: ${relPath}`);
  }

  // Resolve against the root and verify textual containment.
  const resolved = path.resolve(root, normalizedInput);
  if (!isInside(root, resolved)) {
    throw new PathSecurityError(`Path escapes the session directory: ${relPath}`);
  }

  // Symlink-escape check: realpath the deepest existing ancestor and re-verify.
  const existing = deepestExistingAncestor(resolved, root);
  let realExisting: string;
  let realRoot: string;
  try {
    realExisting = fs.realpathSync(existing);
    realRoot = fs.realpathSync(root);
  } catch {
    // Root may not exist yet (new session). Nothing to resolve through a
    // symlink, so the textual check above is sufficient.
    return resolved;
  }
  if (!isInside(realRoot, realExisting)) {
    throw new PathSecurityError(`Path escapes the session directory via a symlink: ${relPath}`);
  }

  return resolved;
}
